SELECT id, symbol, observed_at, price, delivery_status, outcome_reason, created_at FROM crypto_ai.market_price_event WHERE (symbol = 'SHIBUSDT' AND observed_at BETWEEN '2026-10-12 07:14:50' AND '2026-10-12 07:16:00') OR (symbol = 'ACEUSDT' AND observed_at BETWEEN '2026-10-12 10:04:55' AND '2026-10-12 10:05:30') OR (symbol = 'EGLDUSDT' AND observed_at BETWEEN '2026-10-11 21:00:00' AND '2026-10-11 21:00:12') OR (symbol = 'XRPUSDT' AND observed_at BETWEEN '2026-10-12 03:30:00' AND '2026-10-12 03:30:06') ORDER BY symbol, observed_at, id LIMIT 200